 "content": "def transform(grid):
    """Complete single-cell horizontal gaps, project them upward, and extend bottom markers."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    sources = []
    blockers = [[grid[r][c] != 0 for c in range(w)] for r in range(h)]

    # Complete one-cell gaps between equal-color horizontal runs.
    for r in range(h):
        c = 0
        runs = []
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            color = grid[r][c]
            start = c
            while c < w and grid[r][c] == color:
                c += 1
            runs.append((start, c - 1, color))

        for left, right in zip(runs, runs[1:]):
            gap_start, gap_end = left[1] + 1, right[0] - 1
            if gap_end - gap_start + 1 != 1:
                continue
            gc = gap_start
            if left[2] == right[2]:
                color = left[2]
            else:
                left_len = left[1] - left[0] + 1
                right_len = right[1] - right[0] + 1
                color = left[2] if left_len >= right_len else right[2]
            out[r][gc] = color
            blockers[r][gc] = True
            sources.append((r, gc, color))

    # Bottom-edge vertical markers form a background layer; horizontal bars
    # and their projected rays take precedence over these strokes.
    if h:
        for c in range(w):
            color = grid[h - 1][c]
            if color:
                for r in range(h):
                    if not blockers[r][c]:
                        out[r][c] = color

    # Each horizontal gap projects upward, stopping at the first horizontal
    # cell/beam already established in that column.
    for r, c, color in sorted(sources):
        rr = r - 1
        while rr >= 0 and not blockers[rr][c]:
            out[rr][c] = color
            blockers[rr][c] = True
            rr -= 1

    return out
